#include <iostream>
#include <vector>
#include <string>

// Framebuffer simulation of BGI state machine in standard C++17
class SimpleGraphics {
private:
    int width, height;
    std::vector<std::vector<char>> buffer;
    int curX = 0, curY = 0;
    char drawColor = '*';
    char bgColor = '.';

public:
    SimpleGraphics(int w, int h) : width(w), height(h), buffer(h, std::vector<char>(w, '.')) {}

    void setColor(char c) { drawColor = c; }
    void setBkColor(char c) { bgColor = c; }
    char getColor() const { return drawColor; }
    char getBkColor() const { return bgColor; }
    int getX() const { return curX; }
    int getY() const { return curY; }

    void moveto(int x, int y) {
        curX = x;
        curY = y;
    }

    void putpixel(int x, int y, char c) {
        if (x >= 0 && x < width && y >= 0 && y < height) {
            buffer[y][x] = c;
        }
    }

    // Bresenham-like stepping for horizontal/vertical segments
    void lineto(int x2, int y2) {
        int x1 = curX, y1 = curY;
        int dx = (x2 > x1) ? 1 : (x2 < x1 ? -1 : 0);
        int dy = (y2 > y1) ? 1 : (y2 < y1 ? -1 : 0);
        int cx = x1, cy = y1;
        while (true) {
            putpixel(cx, cy, drawColor);
            if (cx == x2 && cy == y2) break;
            if (cx != x2) cx += dx;
            if (cy != y2) cy += dy;
        }
        curX = x2;
        curY = y2;
    }

    void linerel(int dx, int dy) {
        lineto(curX + dx, curY + dy);
    }

    void render() const {
        for (int y = 0; y < height; ++y) {
            for (int x = 0; x < width; ++x) {
                std::cout << buffer[y][x];
            }
            std::cout << '\n';
        }
    }
};

int main() {
    SimpleGraphics g(10, 5);
    g.setColor('#');
    g.moveto(1, 1);
    g.lineto(5, 1); // horizontal line
    g.linerel(0, 2); // relative vertical step
    g.render();
    std::cout << "Cursor: (" << g.getX() << ", " << g.getY() << ")\n";
    return 0;
}

#include <iostream>
#include <cstdint>
#include <string>

// Constants replicating BGI styles
constexpr int SOLID_LINE = 0;
constexpr int DOTTED_LINE = 1;
constexpr int USERBIT_LINE = 4;
constexpr int NORM_WIDTH = 1;
constexpr int THICK_WIDTH = 3;

struct LineSettingsType {
    int linestyle;
    uint16_t upattern;
    int thickness;
};

class StyleRenderer {
private:
    LineSettingsType settings{SOLID_LINE, 0xFFFF, NORM_WIDTH};

public:
    void setlinestyle(int style, uint16_t pattern, int width) {
        settings.linestyle = style;
        settings.upattern = pattern;
        settings.thickness = width;
    }

    void getlinesettings(LineSettingsType* info) const {
        if (info) *info = settings;
    }

    void drawSampleLine(int length) const {
        uint16_t mask = 0xFFFF;
        if (settings.linestyle == DOTTED_LINE) {
            mask = 0xAAAA; // alternating dots: 1010101010101010
        } else if (settings.linestyle == USERBIT_LINE) {
            mask = settings.upattern;
        }

        for (int row = 0; row < settings.thickness; ++row) {
            for (int i = 0; i < length; ++i) {
                bool bitOn = (mask >> (15 - (i % 16))) & 1;
                std::cout << (bitOn ? '-' : ' ');
            }
            std::cout << '\n';
        }
    }
};

int main() {
    StyleRenderer sr;
    std::cout << "Solid normal line:\n";
    sr.setlinestyle(SOLID_LINE, 0, NORM_WIDTH);
    sr.drawSampleLine(16);

    std::cout << "Dotted thick line:\n";
    sr.setlinestyle(DOTTED_LINE, 0, THICK_WIDTH);
    sr.drawSampleLine(16);

    std::cout << "User-defined bit pattern (0xCC33):\n";
    sr.setlinestyle(USERBIT_LINE, 0xCC33, NORM_WIDTH);
    sr.drawSampleLine(16);

    LineSettingsType current;
    sr.getlinesettings(&current);
    std::cout << "Current style: " << current.linestyle 
              << ", thickness: " << current.thickness << '\n';
    return 0;
}
